"use client";
/* Cloud, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Cloud(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("cloud"); }, []);
  return React.createElement("piix-sprite", { "name": "cloud", ...piixAttrs(props) });
}

export default Cloud;
